class Solution { bool isPrime(int value){if(value<2)return false;for(int divisor=2;divisor<=value/divisor;++divisor)if(value%divisor==0)return false;return true;}public:int diagonalPrime(vector<vector<int>>& nums){int answer=0,n=nums.size();for(int i=0;i<n;++i){if(isPrime(nums[i][i]))answer=max(answer,nums[i][i]);if(isPrime(nums[i][n-1-i]))answer=max(answer,nums[i][n-1-i]);}return answer;} };
